    #[test]
    fn model_value_final_cancel_never_acknowledges_output_or_assigns_evidence() {
        struct CancelValue;
        impl RoleModel for CancelValue {
            fn identity(&self) -> &str {
                LegalOrderRoleMock.identity()
            }
            fn value_identity(&self) -> Option<&ModelValueIdentity> {
                LegalOrderRoleMock.value_identity()
            }
            fn evaluate_value(
                &mut self,
                query: RoleQuery<'_>,
            ) -> Result<ModelValueOutput, RoleError> {
                let cancel = query.cancel;
                let output = LegalOrderRoleMock.evaluate_value(query)?;
                cancel.store(true, Ordering::Release);
                Ok(output)
            }
            fn propose(&mut self, query: RoleQuery<'_>) -> Result<RoleEvaluation, RoleError> {
                LegalOrderRoleMock.propose(query)
            }
            fn reply(&mut self, query: RoleQuery<'_>) -> Result<RoleEvaluation, RoleError> {
                LegalOrderRoleMock.reply(query)
            }
            fn repair(&mut self, query: RoleQuery<'_>) -> Result<RoleEvaluation, RoleError> {
                LegalOrderRoleMock.repair(query)
            }
            fn divergences(&mut self, query: DivergenceQuery<'_>) -> Result<Vec<f32>, RoleError> {
                LegalOrderRoleMock.divergences(query)
            }
            fn accepted_output(&mut self) {
                panic!("canceled model value must not be acknowledged");
            }
        }
        let position = Position::startpos();
        let mut engine = PalsEngine::new_with_checker(
            PalsConfig::default(),
            CancelValue,
            ForeignFixture::new(ForeignFixtureMode::Normal(100)),
        )
        .unwrap();
        engine
            .semantic
            .stores
            .focus_actual_moves(position.snapshot())
            .unwrap();
        let root = engine.intern(position).unwrap();
        let mut counters = PalsCounters::default();
        assert!(matches!(
            engine.evaluate_model_value(
                root,
                &[],
                limits(),
                &AtomicBool::new(false),
                &mut counters
            ),
            Err(PalsError::Role(RoleError::Canceled))
        ));
        assert_eq!(counters.value_calls, 1);
        assert_eq!(counters.completed_value_calls, 1);
        assert_eq!(counters.accepted_value_outputs, 0);
        assert!(engine.semantic.nodes[root].model_value.is_none());
    }
    #[test]
    fn restricted_terminal_line_retains_actual_leaf_without_all_defenses_claim() {
        let position = Position::from_fen("7k/5K2/6Q1/8/8/8/8/8 w - - 0 1").unwrap();
        let mut engine = foreign_engine(ForeignFixtureMode::Normal(-999));
        engine
            .semantic
            .stores
            .focus_actual_moves(position.snapshot())
            .unwrap();
        let root = engine.intern(position.clone()).unwrap();
        let mut counters = PalsCounters::default();
        let (movement, child) = position
            .legal_moves()
            .into_iter()
            .find_map(|movement| {
                let mut child = position.clone();
                child.make_move(movement).unwrap();
                matches!(
                    child.classify_position().unwrap().play_status,
                    PlayStatus::Terminal {
                        reason: TerminalReason::Checkmate,
                        ..
                    }
                )
                .then_some((movement, child))
            })
            .unwrap();
        let leaf = engine
            .connect(root, movement, child, &mut counters)
            .unwrap();
        assert!(matches!(
            engine.rules_value(leaf),
            PalsResolvedValue::RulesTerminal {
                winner: Some(Color::White),
                ..
            }
        ));
        assert!(matches!(
            engine.model_value(root, 1),
            PalsResolvedValue::RestrictedRulesLine {
                winner: Some(Color::White),
                ..
            }
        ));
        assert!(engine.semantic.nodes[root].terminal.is_none());
        let result = engine
            .model_result(
                root,
                &position.legal_moves(),
                PalsCompletion::RoundLimit,
                Instant::now(),
                &mut counters,
            )
            .unwrap();
        assert_eq!(result.best_move, Some(movement));
        assert_eq!(result.score, None);
        assert_eq!(result.terminal, None);
        assert!(result.counters.unknown_root_children > 0);
        assert!(matches!(
            result.resolved_value,
            PalsResolvedValue::RulesTerminal {
                winner: Some(Color::White),
                ..
            }
        ));
    }

    fn engine() -> PalsEngine<LegalOrderRoleMock> {
        PalsEngine::new(
            PalsConfig::default(),
            LegalOrderRoleMock,
            CpuEngine::new(CpuConfig {
                max_depth: 4,
                tt_entries: 128,
                quiescence_ply: 8,
                ..CpuConfig::default()
            })
            .unwrap(),
        )
        .unwrap()
    }
    fn limits() -> PalsLimits {
        PalsLimits {
            deadline: Instant::now() + Duration::from_secs(20),
            max_rounds: 1,
            max_cpu_nodes: 2000,
            cpu_depth: 1,
        }
    }

    #[derive(Default)]
    struct RecheckRoleFixture {
        replies: Vec<RoleLogicalContext>,
        fresh_continuation: bool,
        cancel_reply_number: Option<usize>,
        invalid_reply_number: Option<usize>,
        cancel_after_reply: bool,
        cancel_after_prepare: bool,
        cancel_after_finish: bool,
        finish_cross_deadline: bool,
        prepare_error: Option<RoleError>,
        reply_error: Option<RoleError>,
        finish_error: Option<RoleError>,
        prepared: Vec<(RecheckIdentity, RoleLogicalContext, Instant)>,
        finished: Vec<RecheckFinishFixture>,
    }
    struct RecheckFinishFixture {
        policy: PostRepairRecheckPolicy,
        identity: RecheckIdentity,
        prepared_accepted: bool,
        attempted: bool,
        accepted: bool,
        selected: Option<BoardMove>,
        counterline: Vec<BoardMove>,
        full_suffix: bool,
        counterline_completed: bool,
        comparable: bool,
        repaired_observed: bool,
        repaired_invalid: bool,
        counter_observed: Option<bool>,
        publication: Option<(ObservationId, ContinuationConclusion)>,
        disposition: RecheckDisposition,
        original_role_error: Option<RoleError>,
        original_failed: bool,
        deadline: Instant,
    }
    impl RoleModel for RecheckRoleFixture {
        fn identity(&self) -> &str {
            "post-repair-recheck-context-fixture/1"
        }
        fn propose(&mut self, query: RoleQuery<'_>) -> Result<RoleEvaluation, RoleError> {
            LegalOrderRoleMock.propose(query)
        }
        fn reply(&mut self, query: RoleQuery<'_>) -> Result<RoleEvaluation, RoleError> {
            let preferred =
                BoardMove::from_uci(match (self.fresh_continuation, query.prefix.len()) {
                    (true, 4) => "d2d4",
                    (true, 5) => "e5d4",
                    _ => "g8f6",
                })
                .unwrap();
            let preferred_index = query
                .legal
                .iter()
                .position(|movement| *movement == preferred);
            let mut result = LegalOrderRoleMock.reply(query)?;
            if let Some(index) = preferred_index {
                result.logits[index] = 100.0;
            }
            Ok(result)
        }
        fn repair(&mut self, query: RoleQuery<'_>) -> Result<RoleEvaluation, RoleError> {
            let preferred = BoardMove::from_uci("f1c4").unwrap();
            let preferred_index = query
                .legal
                .iter()
                .position(|movement| *movement == preferred);
            let mut result = LegalOrderRoleMock.repair(query)?;
            if let Some(index) = preferred_index {
                result.logits[index] = 100.0;
            }
            Ok(result)
        }
        fn divergences(&mut self, query: DivergenceQuery<'_>) -> Result<Vec<f32>, RoleError> {
            LegalOrderRoleMock.divergences(query)
        }
        fn reply_with_context(
            &mut self,
            query: RoleQuery<'_>,
            context: &RoleLogicalContext,
        ) -> Result<RoleEvaluation, RoleError> {
            self.replies.push(context.clone());
            if let Some(error) = &self.reply_error {
                return Err(error.clone());
            }
            let cancel = query.cancel;
            let mut result = self.reply(query)?;
            if self.invalid_reply_number == Some(self.replies.len()) {
                result.logits.pop();
            }
            if self.cancel_after_reply || self.cancel_reply_number == Some(self.replies.len()) {
                cancel.store(true, Ordering::Release);
            }
            Ok(result)
        }
        fn recheck_prepared(&mut self, prepared: RecheckPrepared<'_>) -> Result<(), RoleError> {
            assert_eq!(prepared.repair_record.kind, RecordKind::Repair);
            assert_eq!(
                prepared.repair_record.revision,
                prepared.identity.repair_record_revision
            );
            assert_eq!(prepared.repair_record.line.as_slice(), prepared.repaired);
            assert_eq!(
                prepared.reply_context.prefix,
                prepared.repaired[..prepared.anchor_ply]
            );
            assert_eq!(prepared.reply_context.state, prepared.anchor_state);
            assert_eq!(prepared.reply_context.situation, prepared.anchor_situation);
            assert_eq!(
                prepared.reply_context.search_generation,
                prepared.identity.search_generation
            );
            let mut checked = Position::startpos();
            assert!(prepared.root_snapshot.same_state(&checked.snapshot()));
            for movement in &prepared.reply_context.prefix {
                checked.make_move(*movement).unwrap();
            }
            assert!(prepared.anchor_snapshot.same_state(&checked.snapshot()));
            if prepared.policy == PostRepairRecheckPolicy::ActualOpponentContinuationV1 {
                assert!(
                    prepared
                        .examined_responses
                        .contains(&prepared.repaired[prepared.anchor_ply])
                );
                let legal = checked.legal_moves();
                for (i, movement) in prepared.examined_responses.iter().enumerate() {
                    assert!(legal.contains(movement));
                    assert!(!prepared.examined_responses[..i].contains(movement));
                }
            } else {
                assert!(prepared.examined_responses.is_empty());
            }
            self.prepared.push((
                prepared.identity,
                prepared.reply_context.clone(),
                prepared.limits.deadline,
            ));
            if self.cancel_after_prepare {
                prepared.cancel.store(true, Ordering::Release);
            }
            match &self.prepare_error {
                Some(error) => Err(error.clone()),
                None => Ok(()),
            }
        }
        fn recheck_finished(&mut self, finished: RecheckFinished<'_>) -> Result<(), RoleError> {
            if let Some(publication) = &finished.publication {
                assert_eq!(
                    publication.conclusion.evidence,
                    Some(publication.observation_id)
                );
                assert_eq!(
                    publication.observation.line,
                    Some(finished.identity.repaired_line)
                );
                assert_eq!(publication.observation.kind, ObservationKind::Refutation);
            }
            self.finished.push(RecheckFinishFixture {
                policy: finished.policy,
                identity: finished.identity,
                prepared_accepted: finished.prepared_accepted,
                attempted: finished.reply_call_attempted,
                accepted: finished.reply_accepted,
                selected: finished.selected_response,
                counterline: finished.counterline.to_vec(),
                full_suffix: finished.full_suffix_replayed,
                counterline_completed: finished.counterline_completed,
                comparable: finished.comparable,
                repaired_observed: matches!(
                    finished.repaired_endpoint.evidence,
                    RecheckEndpointEvidence::OwnCpu { .. }
                ),
                repaired_invalid: matches!(
                    finished.repaired_endpoint.evidence,
                    RecheckEndpointEvidence::InvalidProvenance { .. }
                ),
                counter_observed: finished.counter_endpoint.as_ref().map(|endpoint| {
                    matches!(endpoint.evidence, RecheckEndpointEvidence::OwnCpu { .. })
                }),
                publication: finished
                    .publication
                    .map(|publication| (publication.observation_id, publication.conclusion)),
                disposition: finished.disposition,
                original_role_error: match finished.original_error {
                    Some(PalsError::Role(error)) => Some(error.clone()),
                    _ => None,
                },
                original_failed: finished.original_error.is_some(),
                deadline: finished.limits.deadline,
            });
            if self.finish_cross_deadline {
                // Finite fixture callback work, charged to the original wall.
                let remaining = finished
                    .limits
                    .deadline
                    .saturating_duration_since(Instant::now());
                std::thread::sleep(remaining.saturating_add(Duration::from_millis(1)));
            }
            if self.cancel_after_finish {
                finished.cancel.store(true, Ordering::Release);
            }
            match &self.finish_error {
                Some(error) => Err(error.clone()),
                None => Ok(()),
            }
        }
    }

    /// White-box evidence fixture, not an actual CPU/NN/process acceptance run.
    /// Completed cache values isolate conclusion scope from chess strength;
    /// the one-node case below exercises the real bounded CPU incomplete path.
    struct RecheckFixture {
        engine: PalsEngine<RecheckRoleFixture>,
        root: usize,
        leaf: usize,
        old_line: LineId,
        repaired_line: LineId,
        repair_record_revision: u64,
        repair_evidence: ObservationId,
        repaired: Vec<BoardMove>,
        refutation: Vec<BoardMove>,
        counters: PalsCounters,
    }
    impl RecheckFixture {
        fn run(&mut self, limits: PalsLimits, cancel: &AtomicBool) -> Result<(), PalsError> {
            self.engine.recheck_repaired_line(
                CompletedRepairRecheck {
                    root: self.root,
                    original_first: self.repaired[0],
                    attack_ply: 1,
                    repaired_line: self.repaired_line,
                    repair_record_revision: self.repair_record_revision,
                    repaired_leaf: self.leaf,
                    repaired: &self.repaired,
                    refutation: &self.refutation,
                    completed_value: 100,
                },
                limits,
                cancel,
                &mut self.counters,
                &mut |_, _, _| {},
            )
        }
    }
    fn recheck_fixture(
        policy: PostRepairRecheckPolicy,
        counter_complete: bool,
        incompatible_suffix: bool,
    ) -> RecheckFixture {
        fn moves(text: &[&str]) -> Vec<BoardMove> {
            text.iter()
                .map(|movement| BoardMove::from_uci(movement).unwrap())
                .collect()
        }
        let proposal = moves(&["e2e4", "c7c5", "g1f3", "d7d6", "d2d3", "b8c6"]);
        let (repaired, refutation, mut counter) = if incompatible_suffix {
            (
                moves(&["e2e4", "e7e5", "f1c4", "d7d5", "e4d5", "g8f6"]),
                moves(&["e2e4", "e7e5", "g1f3", "d7d5", "e4d5", "g8f6"]),
                moves(&["e2e4", "e7e5", "f1c4", "g8f6"]),
            )
        } else {
            (
                moves(&["e2e4", "e7e5", "f1c4", "b8c6", "d2d3", "d7d6"]),
                moves(&["e2e4", "e7e5", "g1f3", "b8c6", "d2d3", "d7d6"]),
                moves(&["e2e4", "e7e5", "f1c4", "g8f6", "d2d3", "d7d6"]),
            )
        };
        let fresh_continuation = policy == PostRepairRecheckPolicy::ActualOpponentContinuationV1;
        if fresh_continuation {
            counter = moves(&["e2e4", "e7e5", "f1c4", "g8f6", "d2d4", "e5d4"]);
        }
        let mut engine = PalsEngine::new_with_cpu_and_refinement_policy(
            PalsConfig {
                line_plies: 6,
                ..PalsConfig::default()
            },
            RecheckRoleFixture {
                fresh_continuation,
                ..RecheckRoleFixture::default()
            },
            CpuEngine::new(CpuConfig {
                max_depth: 4,
                tt_entries: 128,
                ..CpuConfig::default()
            })
            .unwrap(),
            policy,
        )
        .unwrap();
        let position = Position::startpos();
        engine
            .semantic
            .stores
            .focus_actual_moves(position.snapshot())
            .unwrap();
        let root = engine.intern(position.clone()).unwrap();
        let mut counters = PalsCounters::default();
        let mut path = vec![root];
        let mut node = root;
        for movement in &repaired {
            let mut child = engine.semantic.nodes[node].position.clone();
            child.make_move(*movement).unwrap();
            node = engine
                .connect(node, *movement, child, &mut counters)
                .unwrap();
            path.push(node);
        }
        let leaf = node;
        let identity = engine.owned_identity().unwrap().clone();
        engine.semantic.nodes[leaf].evidence = Some(CpuEvidence {
            context: None,
            score: 100,
            depth: 1,
            scope: CpuScoreScope::CompletedIteration,
            value_identity: identity.clone(),
            provenance: None,
        });
        if counter_complete {
            let mut counter_position = position;
            for movement in &counter {
                counter_position.make_move(*movement).unwrap();
            }
            // Intern the leaf without connecting its anchor edge, so C's
            // preferred alternative remains the first unexamined response.
            let counter_leaf = engine.intern(counter_position).unwrap();
            engine.semantic.nodes[counter_leaf].evidence = Some(CpuEvidence {
                context: None,
                score: -100,
                depth: 1,
                scope: CpuScoreScope::CompletedIteration,
                value_identity: identity,
                provenance: None,
            });
        }
        let (old_line, _) = engine
            .record(RecordKind::Proposal, &proposal, None, 0, None, None)
            .unwrap()
            .unwrap();
        let old_evidence = engine
            .conclusion_observation(root, old_line, ObservationKind::Refutation, 50, None)
            .unwrap();
        engine
            .semantic
            .stores
            .refute_continuation(
                engine.semantic.nodes[root].situation,
                old_line,
                old_evidence,
            )
            .unwrap();
        let ranked = engine
            .ranked(
                path[2],
                Call::Repair,
                &repaired[..2],
                &proposal,
                Some(&refutation),
                limits(),
                &AtomicBool::new(false),
                &mut counters,
            )
            .unwrap();
        assert_eq!(ranked[0], repaired[2]);
        let (repaired_line, _) = engine
            .record(RecordKind::Repair, &repaired, None, 0, None, None)
            .unwrap()
            .unwrap();
        let repair_record_revision = engine.semantic.revision;
        let repair_evidence = engine
            .conclusion_observation(
                root,
                repaired_line,
                ObservationKind::Repair,
                100,
                Some(old_evidence),
            )
            .unwrap();
        engine
            .semantic
            .stores
            .repair(
                engine.semantic.nodes[root].situation,
                old_line,
                repaired_line,
                repair_evidence,
            )
            .unwrap();
        RecheckFixture {
            engine,
            root,
            leaf,
            old_line,
            repaired_line,
            repair_record_revision,
            repair_evidence,
            repaired,
            refutation,
            counters,
        }
    }

    #[test]
    fn recheck_observer_keeps_manual_values_unobserved_and_links_actual_publication() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        let requested = limits();
        fixture.run(requested, &AtomicBool::new(false)).unwrap();
        assert_eq!(fixture.engine.semantic.model.prepared.len(), 1);
        assert_eq!(fixture.engine.semantic.model.finished.len(), 1);
        let finished = &fixture.engine.semantic.model.finished[0];
        assert_eq!(
            finished.identity,
            fixture.engine.semantic.model.prepared[0].0
        );
        assert_eq!(finished.deadline, requested.deadline);
        assert!(finished.prepared_accepted && finished.attempted && finished.accepted);
        assert_eq!(
            finished.selected,
            Some(BoardMove::from_uci("g8f6").unwrap())
        );
        assert_eq!(finished.counterline.len(), fixture.repaired.len());
        assert!(finished.full_suffix && finished.comparable);
        assert!(!finished.repaired_observed && !finished.repaired_invalid);
        assert_eq!(finished.counter_observed, Some(false));
        assert!(!finished.original_failed);
        assert_eq!(
            finished.disposition,
            RecheckDisposition::ConditionalRefutationPublished
        );
        let (observation, conclusion) = finished.publication.unwrap();
        assert_eq!(conclusion.evidence, Some(observation));
        assert_eq!(
            fixture
                .engine
                .semantic
                .stores
                .situations
                .get(finished.identity.root)
                .unwrap()
                .conclusions
                .get(finished.identity.repaired_line)
                .copied(),
            Some(conclusion)
        );
        assert_eq!(fixture.engine.last_recheck_observer_error(), None);
    }

    #[test]
    fn recheck_preparation_rejection_finishes_without_reply_and_preserves_secondary_error() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        let primary = RoleError::Backend("observer reservation refused".into());
        let secondary = RoleError::Backend("observer close failed".into());
        fixture.engine.semantic.model.prepare_error = Some(primary.clone());
        fixture.engine.semantic.model.finish_error = Some(secondary.clone());
        assert!(
            matches!(fixture.run(limits(), &AtomicBool::new(false)), Err(PalsError::Role(error)) if error == primary)
        );
        assert_eq!(fixture.engine.semantic.model.prepared.len(), 1);
        assert_eq!(fixture.engine.semantic.model.finished.len(), 1);
        assert!(fixture.engine.semantic.model.replies.is_empty());
        let finished = &fixture.engine.semantic.model.finished[0];
        assert!(!finished.prepared_accepted && !finished.attempted && !finished.accepted);
        assert!(finished.counterline.is_empty());
        assert_eq!(finished.disposition, RecheckDisposition::PreparedRejected);
        assert_eq!(finished.original_role_error.as_ref(), Some(&primary));
        assert_eq!(
            fixture.engine.last_recheck_observer_error(),
            Some(&secondary)
        );
        assert_eq!(fixture.counters.critic_calls, 0);
        assert_eq!(fixture.counters.supported_refutations, 0);
    }

    #[test]
    fn recheck_reply_failure_and_observer_failure_keep_original_error_and_no_publication() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        let primary = RoleError::PhysicalCompletionUnknown;
        let secondary = RoleError::Backend("observer close failed".into());
        fixture.engine.semantic.model.reply_error = Some(primary.clone());
        fixture.engine.semantic.model.finish_error = Some(secondary.clone());
        fixture.engine.semantic.model.cancel_after_finish = true;
        assert!(
            matches!(fixture.run(limits(), &AtomicBool::new(false)), Err(PalsError::Role(error)) if error == primary)
        );
        assert_eq!(fixture.engine.semantic.model.finished.len(), 1);
        let finished = &fixture.engine.semantic.model.finished[0];
        assert!(finished.prepared_accepted && finished.attempted && !finished.accepted);
        assert!(
            finished.selected.is_none()
                && finished.counterline.is_empty()
                && finished.publication.is_none()
        );
        assert_eq!(finished.original_role_error, Some(primary));
        assert_eq!(
            fixture.engine.last_recheck_observer_error(),
            Some(&secondary)
        );
        assert_eq!(fixture.counters.completed_critic_calls, 0);
    }

    #[test]
    fn recheck_cancel_after_preparation_or_reply_still_finishes_original_controls_once() {
        for after_reply in [false, true] {
            let mut fixture =
                recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
            fixture.engine.semantic.model.cancel_after_prepare = !after_reply;
            fixture.engine.semantic.model.cancel_after_reply = after_reply;
            let requested = limits();
            let cancel = AtomicBool::new(false);
            assert!(matches!(
                fixture.run(requested, &cancel),
                Err(PalsError::Role(RoleError::Canceled))
            ));
            assert_eq!(fixture.engine.semantic.model.prepared.len(), 1);
            assert_eq!(fixture.engine.semantic.model.finished.len(), 1);
            let finished = &fixture.engine.semantic.model.finished[0];
            assert!(finished.prepared_accepted);
            assert_eq!(finished.attempted, after_reply);
            assert!(!finished.accepted);
            assert_eq!(finished.deadline, requested.deadline);
            assert_eq!(finished.original_role_error, Some(RoleError::Canceled));
            assert!(finished.publication.is_none());
        }
    }

    #[test]
    fn recheck_successful_finish_rechecks_external_cancel_at_return_boundary() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        fixture.engine.semantic.model.cancel_after_finish = true;
        let requested = limits();
        let cancel = AtomicBool::new(false);
        assert!(matches!(
            fixture.run(requested, &cancel),
            Err(PalsError::Role(RoleError::Canceled))
        ));
        assert!(cancel.load(Ordering::Acquire));
        assert_eq!(fixture.engine.semantic.model.finished.len(), 1);
        assert!(!fixture.engine.semantic.model.finished[0].original_failed);
        assert!(
            fixture.engine.semantic.model.finished[0]
                .publication
                .is_some()
        );
        assert_eq!(
            fixture.engine.semantic.model.finished[0].deadline,
            requested.deadline
        );
        assert_eq!(fixture.engine.last_recheck_observer_error(), None);
    }

    #[test]
    fn recheck_successful_finish_time_is_charged_to_original_deadline() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        fixture.engine.semantic.model.finish_cross_deadline = true;
        let requested = PalsLimits {
            deadline: Instant::now() + Duration::from_millis(100),
            ..limits()
        };
        assert!(matches!(
            fixture.run(requested, &AtomicBool::new(false)),
            Err(PalsError::Role(RoleError::Deadline))
        ));
        assert_eq!(fixture.engine.semantic.model.finished.len(), 1);
        assert!(!fixture.engine.semantic.model.finished[0].original_failed);
        assert!(
            fixture.engine.semantic.model.finished[0]
                .publication
                .is_some()
        );
        assert_eq!(
            fixture.engine.semantic.model.finished[0].deadline,
            requested.deadline
        );
        assert!(Instant::now() >= requested.deadline);
        assert_eq!(fixture.engine.last_recheck_observer_error(), None);
    }

    #[test]
    fn recheck_finish_error_is_typed_and_reset_on_new_game_and_search() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        let secondary = RoleError::Backend("observer close failed".into());
        fixture.engine.semantic.model.finish_error = Some(secondary.clone());
        assert!(
            matches!(fixture.run(limits(), &AtomicBool::new(false)), Err(PalsError::Role(error)) if error == secondary)
        );
        assert!(!fixture.engine.semantic.model.finished[0].original_failed);
        assert_eq!(
            fixture.engine.last_recheck_observer_error(),
            Some(&secondary)
        );
        fixture.engine.new_game();
        assert_eq!(fixture.engine.last_recheck_observer_error(), None);
        fixture.engine.semantic.last_recheck_observer_error = Some(secondary);
        assert!(matches!(
            fixture.engine.search(
                &Position::startpos(),
                PalsLimits {
                    max_rounds: 0,
                    ..limits()
                },
                &AtomicBool::new(false)
            ),
            Err(PalsError::InvalidLimits)
        ));
        assert_eq!(fixture.engine.last_recheck_observer_error(), None);
    }

    #[test]
    fn recheck_actual_append_and_reuse_preserve_exact_observation_execution_and_task() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        fixture.engine.semantic.nodes[fixture.leaf].evidence = None;
        let requested = limits();
        let cancel = AtomicBool::new(false);
        let mut first = PalsCounters::default();
        fixture
            .engine
            .verify(
                fixture.leaf,
                &fixture.repaired,
                requested,
                &cancel,
                &mut first,
            )
            .unwrap();
        let ids = fixture.engine.semantic.nodes[fixture.leaf]
            .evidence
            .as_ref()
            .unwrap()
            .provenance
            .unwrap();
        let snapshot = fixture.engine.semantic.nodes[fixture.leaf]
            .position
            .snapshot();
        let endpoint = PalsEngine::<RecheckRoleFixture>::recheck_endpoint(
            &fixture.engine.semantic.nodes[fixture.leaf],
            &fixture.engine.semantic.stores,
            &snapshot,
        );
        match endpoint.evidence {
            RecheckEndpointEvidence::OwnCpu {
                observation_id,
                execution_id,
                observation,
                task,
                admitted_scope,
            } => {
                assert_eq!((observation_id, execution_id), ids);
                assert_eq!(observation.execution, Some(execution_id));
                assert_eq!(task.status, TaskStatus::Completed(observation_id));
                assert_eq!(task.key.cpu_condition, observation.cpu_condition);
                assert_eq!(task.key.state, endpoint.state);
                assert_eq!(admitted_scope, CpuScoreScope::CompletedIteration);
            }
            other => panic!("actual completed store evidence missing: {other:?}"),
        }
        fixture.engine.semantic.nodes[fixture.leaf].evidence = None;
        let mut reused = PalsCounters::default();
        fixture
            .engine
            .verify(
                fixture.leaf,
                &fixture.repaired,
                requested,
                &cancel,
                &mut reused,
            )
            .unwrap();
        assert_eq!(
            fixture.engine.semantic.nodes[fixture.leaf]
                .evidence
                .as_ref()
                .unwrap()
                .provenance,
            Some(ids)
        );
        assert_eq!(reused.cpu_tasks_requested, 0);
        assert_eq!(reused.reused_completed_cpu_tasks_consumed, 1);
        fixture.engine.semantic.nodes[fixture.leaf]
            .evidence
            .as_mut()
            .unwrap()
            .depth += 1;
        assert!(matches!(
            PalsEngine::<RecheckRoleFixture>::recheck_endpoint(
                &fixture.engine.semantic.nodes[fixture.leaf],
                &fixture.engine.semantic.stores,
                &snapshot
            )
            .evidence,
            RecheckEndpointEvidence::InvalidProvenance { .. }
        ));
    }

    #[test]
    fn recheck_invalid_provenance_is_distinct_from_absence_and_closes_without_reply() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        fixture.engine.semantic.nodes[fixture.leaf]
            .evidence
            .as_mut()
            .unwrap()
            .provenance = Some((ObservationId(usize::MAX), ExecutionId(usize::MAX)));
        assert!(matches!(
            fixture.run(limits(), &AtomicBool::new(false)),
            Err(PalsError::Store(StoreError::InvalidHandle(_)))
        ));
        assert!(
            fixture.engine.semantic.model.prepared.is_empty()
                && fixture.engine.semantic.model.replies.is_empty()
        );
        assert_eq!(fixture.engine.semantic.model.finished.len(), 1);
        let finished = &fixture.engine.semantic.model.finished[0];
        assert!(finished.repaired_invalid && !finished.repaired_observed);
        assert!(!finished.prepared_accepted && !finished.attempted && finished.original_failed);
        assert_eq!(finished.disposition, RecheckDisposition::PreparedRejected);
    }

    #[test]
    fn recheck_endpoint_distinguishes_rules_terminal_and_actual_incomplete_task() {
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        let mut terminal = Position::startpos();
        for text in ["f2f3", "e7e5", "g2g4", "d8h4"] {
            terminal
                .make_move(BoardMove::from_uci(text).unwrap())
                .unwrap();
        }
        let snapshot = terminal.snapshot();
        let node = fixture.engine.intern(terminal).unwrap();
        assert!(matches!(
            PalsEngine::<RecheckRoleFixture>::recheck_endpoint(
                &fixture.engine.semantic.nodes[node],
                &fixture.engine.semantic.stores,
                &snapshot
            )
            .evidence,
            RecheckEndpointEvidence::RulesTerminal {
                perspective: Color::White,
                ..
            }
        ));
        fixture.engine.semantic.nodes[fixture.leaf].evidence = None;
        let mut work = PalsCounters::default();
        fixture
            .engine
            .verify(
                fixture.leaf,
                &fixture.repaired,
                PalsLimits {
                    max_cpu_nodes: 1,
                    ..limits()
                },
                &AtomicBool::new(false),
                &mut work,
            )
            .unwrap();
        let snapshot = fixture.engine.semantic.nodes[fixture.leaf]
            .position
            .snapshot();
        match PalsEngine::<RecheckRoleFixture>::recheck_endpoint(
            &fixture.engine.semantic.nodes[fixture.leaf],
            &fixture.engine.semantic.stores,
            &snapshot,
        )
        .evidence
        {
            RecheckEndpointEvidence::OwnCpu { task, .. } => {
                assert!(!matches!(task.status, TaskStatus::Completed(_)))
            }
            other => panic!("incomplete actual work lost its raw identity: {other:?}"),
        }
        assert_eq!(work.completed_cpu_tasks, 0);
    }

    #[test]
    fn boxed_recheck_hooks_forward_and_default_mock_hooks_remain_noop() {
        // Direct callback forwarding fixture, not a native/CPU execution witness.
        let fixture = recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        let mut position = Position::startpos();
        for movement in &fixture.repaired[..3] {
            position.make_move(*movement).unwrap();
        }
        let anchor = fixture
            .engine
            .semantic
            .nodes
            .iter()
            .position(|node| node.position.position_identity() == position.position_identity())
            .unwrap();
        let context = fixture
            .engine
            .role_context(
                anchor,
                RoleQuestion {
                    purpose: RoleQueryPurpose::ReplyPolicy,
                    prefix: &fixture.repaired[..3],
                    proposal: &fixture.repaired,
                    refutation: Some(&fixture.refutation),
                    divergences: &[],
                },
            )
            .unwrap();
        let root_snapshot = fixture.engine.semantic.nodes[fixture.root]
            .position
            .snapshot();
        let anchor_snapshot = fixture.engine.semantic.nodes[anchor].position.snapshot();
        let repaired_snapshot = fixture.engine.semantic.nodes[fixture.leaf]
            .position
            .snapshot();
        let requested = limits();
        let cancel = AtomicBool::new(false);
        let identity = RecheckIdentity {
            game_generation: context.game_generation,
            search_generation: context.search_generation,
            root: fixture.engine.semantic.nodes[fixture.root].situation,
            root_revision: fixture
                .engine
                .semantic
                .stores
                .situations
                .get(fixture.engine.semantic.nodes[fixture.root].situation)
                .unwrap()
                .revision,
            repair_record_revision: fixture.repair_record_revision,
            repaired_line: fixture.repaired_line,
        };
        let prepared = || RecheckPrepared {
            policy: fixture.engine.post_repair_recheck_policy(),
            identity,
            root_state: fixture.engine.semantic.nodes[fixture.root].state,
            root_snapshot: &root_snapshot,
            anchor_state: fixture.engine.semantic.nodes[anchor].state,
            anchor_situation: fixture.engine.semantic.nodes[anchor].situation,
            anchor_snapshot: &anchor_snapshot,
            anchor_ply: 3,
            examined_responses: &[],
            reply_context: &context,
            repair_record: fixture
                .engine
                .semantic
                .records
                .iter()
                .find(|record| record.kind == RecordKind::Repair)
                .unwrap(),
            repaired: &fixture.repaired,
            refutation: &fixture.refutation,
            repaired_endpoint: PalsEngine::<RecheckRoleFixture>::recheck_endpoint(
                &fixture.engine.semantic.nodes[fixture.leaf],
                &fixture.engine.semantic.stores,
                &repaired_snapshot,
            ),
            limits: requested,
            deadline_tick: fixture.engine.tick_at(requested.deadline),
            cancel: &cancel,
            config: &fixture.engine.config,
            checker_identity: &fixture.engine.researcher.checker_registered_identity,
            cpu_condition: &fixture.engine.researcher.cpu_registered_condition,
        };
        let finished = || RecheckFinished {
            policy: fixture.engine.post_repair_recheck_policy(),
            identity,
            prepared_accepted: true,
            reply_call_attempted: false,
            reply_accepted: false,
            reply_context: &context,
            selected_response: None,
            counterline: &[],
            full_suffix_replayed: false,
            counterline_completed: false,
            repaired_endpoint: PalsEngine::<RecheckRoleFixture>::recheck_endpoint(
                &fixture.engine.semantic.nodes[fixture.leaf],
                &fixture.engine.semantic.stores,
                &repaired_snapshot,
            ),
            counter_endpoint: None,
            comparable: false,
            publication: None,
            disposition: RecheckDisposition::NoAlternativeResponse,
            original_error: None,
            limits: requested,
            deadline_tick: fixture.engine.tick_at(requested.deadline),
            cancel: &cancel,
        };
        let mut default = LegalOrderRoleMock;
        RoleModel::recheck_prepared(&mut default, prepared()).unwrap();
        RoleModel::recheck_finished(&mut default, finished()).unwrap();
        let mut boxed = Box::new(RecheckRoleFixture::default());
        RoleModel::recheck_prepared(&mut boxed, prepared()).unwrap();
        RoleModel::recheck_finished(&mut boxed, finished()).unwrap();
        assert_eq!(boxed.prepared.len(), 1);
        assert_eq!(boxed.finished.len(), 1);
        assert_eq!(boxed.prepared[0].0, boxed.finished[0].identity);
    }

    #[test]
