    #[test]
    fn post_repair_one_reply_uses_revised_context_and_refutes_only_that_line() {
        use super::super::store::ContinuationStatus;
        let mut fixture =
            recheck_fixture(PostRepairRecheckPolicy::SameRepairedLineOnceV1, true, false);
        fixture.run(limits(), &AtomicBool::new(false)).unwrap();
        assert_eq!(fixture.engine.semantic.model.replies.len(), 1);
        let context = &fixture.engine.semantic.model.replies[0];
        assert_eq!(context.purpose, RoleQueryPurpose::ReplyPolicy);
        assert_eq!(context.prefix, fixture.repaired[..3]);
        assert_eq!(
            context.proposal_sha256,
            role_line_sha256(b"proposal", &fixture.repaired).unwrap()
        );
        assert_eq!(
            context.refutation_sha256,
            Some(role_line_sha256(b"refutation", &fixture.refutation).unwrap())
        );
        assert!(context.public_revision >= fixture.repair_record_revision);
        assert_eq!(fixture.counters.critic_calls, 1);
        assert_eq!(fixture.counters.accepted_critic_outputs, 1);
        assert_eq!(fixture.counters.accepted_repair_outputs, 1);
        assert_eq!(fixture.counters.supported_refutations, 1);
        assert_eq!(fixture.counters.consumed_cached_cpu_values, 1);
        let situation = fixture
            .engine
            .semantic
            .stores
            .situations
            .get(fixture.engine.semantic.nodes[fixture.root].situation)
            .unwrap();
        assert!(situation.dirty);
        assert_eq!(
            situation.conclusions.get(fixture.old_line).unwrap().status,
            ContinuationStatus::RepairedBy(fixture.repaired_line)
        );
        let conclusion = situation.conclusions.get(fixture.repaired_line).unwrap();
        assert_eq!(conclusion.status, ContinuationStatus::Refuted);
        let evidence = fixture
            .engine
            .semantic
            .stores
            .observations
            .get(conclusion.evidence.unwrap())
            .unwrap();
        assert_eq!(evidence.supersedes, Some(fixture.repair_evidence));
        assert_eq!(
            evidence.source,
            stable_id(POST_REPAIR_RECHECK_SEARCH_VERSION)
        );
        assert!(matches!(evidence.scope, EvidenceScope::Model { .. }));
        assert!(
            fixture.engine.semantic.nodes[fixture.root]
                .edges
                .iter()
                .any(|edge| edge.movement == fixture.repaired[0])
        );
    }

    #[test]
    fn post_repair_actual_c_continuation_uses_new_prefixes_not_the_repaired_suffix() {
        use super::super::store::ContinuationStatus;
        for incompatible_suffix in [false, true] {
            let mut fixture = recheck_fixture(
                PostRepairRecheckPolicy::ActualOpponentContinuationV1,
                true,
                incompatible_suffix,
            );
            fixture.run(limits(), &AtomicBool::new(false)).unwrap();
            let expected: Vec<_> = ["e2e4", "e7e5", "f1c4", "g8f6", "d2d4", "e5d4"]
                .iter()
                .map(|text| BoardMove::from_uci(text).unwrap())
                .collect();
            assert_eq!(fixture.engine.semantic.model.replies.len(), 3);
            for (i, context) in fixture.engine.semantic.model.replies.iter().enumerate() {
                assert_eq!(context.prefix, expected[..3 + i]);
                assert_eq!(context.purpose, RoleQueryPurpose::ReplyPolicy);
                assert_eq!(
                    context.proposal_sha256,
                    role_line_sha256(b"proposal", &fixture.repaired).unwrap()
                );
                let mut actual = Position::startpos();
                for movement in &context.prefix {
                    actual.make_move(*movement).unwrap();
                }
                assert!(
                    fixture
                        .engine
                        .semantic
                        .stores
                        .states
                        .get(context.state)
                        .unwrap()
                        .same_state(&actual.snapshot())
                );
            }
            assert_eq!(fixture.counters.critic_calls, 3);
            assert_eq!(fixture.counters.accepted_critic_outputs, 3);
            let finish = &fixture.engine.semantic.model.finished[0];
            assert_eq!(
                finish.policy,
                PostRepairRecheckPolicy::ActualOpponentContinuationV1
            );
            assert_eq!(finish.counterline, expected);
            assert!(finish.counterline_completed);
            assert!(!finish.full_suffix);
            assert!(finish.comparable);
            assert_eq!(fixture.counters.supported_refutations, 1);
            let situation = fixture
                .engine
                .semantic
                .stores
                .situations
                .get(fixture.engine.semantic.nodes[fixture.root].situation)
                .unwrap();
            assert_eq!(
                situation.conclusions.get(fixture.old_line).unwrap().status,
                ContinuationStatus::RepairedBy(fixture.repaired_line)
            );
            let conclusion = situation.conclusions.get(fixture.repaired_line).unwrap();
            assert_eq!(conclusion.status, ContinuationStatus::Refuted);
            let evidence = fixture
                .engine
                .semantic
                .stores
                .observations
                .get(conclusion.evidence.unwrap())
                .unwrap();
            assert_eq!(
                evidence.source,
                stable_id(POST_REPAIR_CONTINUATION_SEARCH_VERSION)
            );
            assert_eq!(evidence.supersedes, Some(fixture.repair_evidence));
            assert_eq!(finish.counterline[0], fixture.repaired[0]);
        }
    }

    #[test]
    fn post_repair_actual_c_continuation_rejects_late_invalid_and_over_budget_tail() {
        for failure in 0..3 {
            let mut fixture = recheck_fixture(
                PostRepairRecheckPolicy::ActualOpponentContinuationV1,
                true,
                false,
            );
            if failure == 0 {
                fixture.engine.semantic.model.cancel_reply_number = Some(2);
            }
            if failure == 1 {
                fixture.engine.semantic.model.invalid_reply_number = Some(2);
            }
            if failure == 2 {
                fixture.engine.config.max_role_calls = fixture.counters.role_calls + 1;
            }
            let result = fixture.run(limits(), &AtomicBool::new(false));
            assert!(matches!(
                (failure, result),
                (0, Err(PalsError::Role(RoleError::Canceled)))
                    | (1, Err(PalsError::Role(RoleError::InvalidOutput)))
                    | (2, Err(PalsError::RoleCallLimit))
            ));
            assert_eq!(fixture.counters.accepted_critic_outputs, 1);
            assert_eq!(fixture.counters.supported_refutations, 0);
            let finish = &fixture.engine.semantic.model.finished[0];
            assert_eq!(finish.counterline.len(), 4);
            assert!(!finish.full_suffix);
            assert!(!finish.counterline_completed);
            assert!(finish.original_failed);
            assert!(finish.publication.is_none());
            assert_eq!(finish.selected, Some(BoardMove::from_uci("g8f6").unwrap()));
            assert_eq!(finish.counterline[0], fixture.repaired[0]);
        }
    }

